import React, { useState } from 'react';

const MainSection = ({ onYes }) => {
  const [hoveredCard, setHoveredCard] = useState(null);

  const reasons = [
    {
      id: 1,
      icon: '✨',
      title: 'You Make Me Smile',
      description: 'Every moment with you lights up my world',
      position: 'top-[5%] left-[50%] -translate-x-1/2',
      rotation: 'rotateX(45deg) rotateY(-30deg) rotateZ(10deg)',
    },
    {
      id: 2,
      icon: '❤️',
      title: 'You\'re My Safe Place',
      description: 'In your arms, I find my home',
      position: 'top-[20%] right-[5%]',
      rotation: 'rotateX(30deg) rotateY(40deg) rotateZ(25deg)',
    },
    {
      id: 3,
      icon: '🏰',
      title: 'You\'re My Forever',
      description: 'With you, I see eternity',
      position: 'top-[45%] right-[8%]',
      rotation: 'rotateX(20deg) rotateY(50deg) rotateZ(15deg)',
    },
    {
      id: 4,
      icon: '🔐',
      title: 'You\'re My Anchor',
      description: 'Steadfast and true',
      position: 'bottom-[20%] right-[15%]',
      rotation: 'rotateX(35deg) rotateY(45deg) rotateZ(20deg)',
    },
    {
      id: 5,
      icon: '💫',
      title: 'You Complete Me',
      description: 'The missing piece of my heart',
      position: 'bottom-[10%] left-[50%] -translate-x-1/2',
      rotation: 'rotateX(50deg) rotateY(0deg) rotateZ(5deg)',
    },
    {
      id: 6,
      icon: '🐝',
      title: 'You\'re Amazing',
      description: 'High integrity, high quality human',
      position: 'bottom-[25%] left-[12%]',
      rotation: 'rotateX(30deg) rotateY(-45deg) rotateZ(-20deg)',
    },
  ];

  const decorativeElements = [
    { id: 1, position: 'top-[25%] left-[35%]', rotation: '45deg', color: 'from-purple-500 to-indigo-500' },
    { id: 2, position: 'top-[20%] right-[30%]', rotation: '-30deg', color: 'from-violet-500 to-purple-500' },
    { id: 3, position: 'bottom-[30%] left-[40%]', rotation: '120deg', color: 'from-indigo-500 to-violet-500' },
    { id: 4, position: 'bottom-[25%] right-[35%]', rotation: '-60deg', color: 'from-purple-600 to-indigo-600' },
  ];

  return (
    <div className="relative w-full min-h-screen flex items-center justify-center overflow-hidden px-4 py-16">
      {/* Decorative triangular elements */}
      {decorativeElements.map((elem) => (
        <div
          key={elem.id}
          className={`absolute ${elem.position} w-16 h-16 md:w-20 md:h-20 opacity-40 animate-float`}
          style={{
            clipPath: 'polygon(50% 0%, 0% 100%, 100% 100%)',
            transform: `rotate(${elem.rotation})`,
            animationDelay: `${elem.id * 0.5}s`,
          }}
        >
          <div className={`w-full h-full bg-gradient-to-br ${elem.color}`}></div>
        </div>
      ))}

      {/* Floating cards */}
      {reasons.map((reason) => (
        <div
          key={reason.id}
          className={`absolute hidden md:block ${reason.position} animate-float-3d`}
          style={{
            transform: `rotate(${reason.rotation})`,
            animationDelay: `${reason.id * 0.3}s`,
          }}
          onMouseEnter={() => setHoveredCard(reason.id)}
          onMouseLeave={() => setHoveredCard(null)}
        >
          <div
            className={`glass p-6 rounded-2xl shadow-xl transition-all duration-500 cursor-pointer w-64 ${
              hoveredCard === reason.id ? 'scale-110 rotate-0 shadow-2xl' : ''
            }`}
          >
            <div className="flex items-start gap-3">
              <div className="text-3xl drop-shadow-lg">{reason.icon}</div>
              <div>
                <h3 className="font-bold text-gray-900 mb-1 text-sm">{reason.title}</h3>
                <p className="text-xs text-gray-600">{reason.description}</p>
              </div>
            </div>
          </div>
        </div>
      ))}

      {/* Central main question */}
      <div className="text-center z-10 max-w-4xl px-4">
        {/* Mobile cards grid */}
        <div className="md:hidden grid grid-cols-2 gap-4 mb-8">
          {reasons.map((reason) => (
            <div key={reason.id} className="glass p-4 rounded-xl shadow-lg">
              <div className="text-2xl mb-2">{reason.icon}</div>
              <h3 className="font-bold text-gray-900 text-sm mb-1">{reason.title}</h3>
              <p className="text-xs text-gray-600">{reason.description}</p>
            </div>
          ))}
        </div>

        {/* Big question */}
        <div className="p-8 md:p-12 lg:p-16 rounded-3xl animate-slide-up">
          <h2 className="text-4xl md:text-6xl lg:text-7xl font-bold mb-8 text-gray-900" style={{ fontFamily: "'Playfair Display', serif" }}>
            So… will you be my <span className="gradient-text" style={{ fontFamily: "'Dancing Script', cursive" }}>Valentine?</span>
          </h2>

          <div className="flex gap-4 justify-center flex-col md:flex-row">
            <button
              onClick={onYes}
              className="px-10 py-5 bg-gradient-to-r from-purple-500 to-indigo-600 text-white font-bold text-xl rounded-full shadow-xl hover:shadow-2xl hover:scale-110 active:scale-95 transition-all duration-300"
            >
              Yes! 💙
            </button>

            <button
              onClick={onYes}
              className="px-10 py-5 bg-white border-2 border-gray-900 text-gray-900 font-bold text-xl rounded-full shadow-lg hover:shadow-xl hover:bg-gray-50 hover:scale-105 active:scale-95 transition-all duration-300"
            >
              Of course! 😌
            </button>
          </div>

          <p className="text-gray-600 mt-8 italic text-sm text-center">
            Spoiler: Both answers lead to the same happy ending 💕
          </p>
        </div>

        {/* Footer */}
        <p className="mt-8 text-gray-600 text-sm font-medium">
          Made with 💙 on passion and love
        </p>
      </div>
    </div>
  );
};

export default MainSection;
